/**
 * The TypeScript side, checked against the firmware's own output.
 *
 *     node --test --experimental-strip-types 'pill_dispenser/webapp_kit/tests/*.test.ts'
 *
 * Same runner and same import style as `lib/hardware/*.test.ts`, so this drops
 * into the app's `npm test` unchanged once the kit is copied in.
 *
 * `vectors.json` is generated by `tools/make_vectors.py`, which imports the
 * actual firmware modules. That is what makes these tests meaningful: they are
 * not this file agreeing with itself, they are this file agreeing with the
 * Python that runs on the Raspberry Pi. Regenerate with `make vectors` after
 * any change to the derivation, and never hand-edit the JSON.
 */
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

import { normaliseClaim, formatClaim, claimFromPairUrl, isValidClaim } from '../src/claim.ts';
import { deriveKeys, deviceId, accessToken, b64url, unb64url, InvalidClaimError } from '../src/derive.ts';
import { seal, unseal, aad, SealError } from '../src/envelope.ts';
import { encodeWeekly, decodeWeekly, normaliseSlots, parseHhmm, formatHhmm, daysToMask, maskToDays, describeDays, ScheduleError } from '../src/schedule.ts';
import { DispenserClient, RelayError, RevisionConflictError } from '../src/relay.ts';
import { EVERY_DAY } from '../src/types.ts';

const vectors = JSON.parse(
  readFileSync(fileURLToPath(new URL('./vectors.json', import.meta.url)), 'utf8'),
);

const hex = (raw: Uint8Array) => [...raw].map((b) => b.toString(16).padStart(2, '0')).join('');
const unhex = (text: string) =>
  new Uint8Array((text.match(/../g) ?? []).map((pair) => parseInt(pair, 16)));

// ── the claim code ──────────────────────────────────────────────────────────

test('claim normalisation matches the firmware, character for character', () => {
  for (const item of vectors.claim.normalise) {
    assert.equal(normaliseClaim(item.input), item.expect, item.why ?? item.input);
  }
});

test('a short code is refused rather than padded', () => {
  // The failure this prevents: a code with a character missing derives a
  // perfectly valid key for a mailbox that does not exist, and the only symptom
  // is a dispenser that appears to have been unplugged.
  assert.equal(normaliseClaim('6V9F59QK6'), '');
  assert.equal(isValidClaim('6V9F59QK6'), false);
  assert.rejects(() => deriveKeys('6V9F59QK6'), InvalidClaimError);
});

test('the display form is hyphenated and derives identically', async () => {
  assert.equal(formatClaim(vectors.claim.sample), vectors.claim.formatted);
  const fromBare = await deviceId(vectors.claim.sample);
  const fromPretty = await deviceId(vectors.claim.formatted);
  assert.equal(fromBare, fromPretty);
  // The token has to survive the hyphen too. The device ID only decides which
  // mailbox is read; the token decides whether the read is allowed. If only the
  // ID normalised, a carer who typed the code the way it is printed on the box
  // would reach the right mailbox and be turned away by it — an authorisation
  // failure with no wrong password behind it, which is close to undebuggable
  // from the phone. deriveKeys covers the pair; this covers the function the
  // relay client actually calls.
  assert.equal(
    await accessToken(vectors.claim.formatted),
    vectors.keys.accessToken,
  );
});

test('the pairing code is read out of the URL fragment', () => {
  assert.equal(
    claimFromPairUrl(`https://relay.example/pair#${vectors.claim.sample}`),
    vectors.claim.sample,
  );
  // No fragment means no code — and a code in the query string is a code in
  // somebody's access log, so it is deliberately not accepted from there.
  assert.equal(claimFromPairUrl(`https://relay.example/pair?code=${vectors.claim.sample}`), '');
});

// ── base64url ───────────────────────────────────────────────────────────────

test('base64url round-trips and never emits padding', () => {
  for (let length = 0; length < 40; length += 1) {
    const raw = new Uint8Array(length).map((_, i) => (i * 37 + length) & 0xff);
    const encoded = b64url(raw);
    assert.ok(!encoded.includes('='), `padding leaked at length ${length}`);
    assert.ok(!/[+/]/.test(encoded), `not url-safe at length ${length}`);
    assert.deepEqual([...unb64url(encoded)], [...raw]);
  }
});

// ── the three keys ──────────────────────────────────────────────────────────

test('HKDF agrees with RFC 5869 test case 1', async () => {
  // Not our own vector — the standard's. This is what establishes that both
  // sides implement the same construction rather than the same mistake.
  const rfc = vectors.hkdfRfc5869;
  const ikm = await crypto.subtle.importKey('raw', unhex(rfc.ikmHex), 'HKDF', false, [
    'deriveBits',
  ]);
  const okm = await crypto.subtle.deriveBits(
    {
      name: 'HKDF',
      hash: 'SHA-256',
      salt: unhex(rfc.saltHex),
      info: unhex(rfc.infoHex),
    },
    ikm,
    rfc.length * 8,
  );
  assert.equal(hex(new Uint8Array(okm)), rfc.okmHex);
});

test('the three keys are exactly what the device derives', async () => {
  const keys = await deriveKeys(vectors.keys.claim);
  assert.equal(keys.deviceId, vectors.keys.deviceId);
  assert.equal(keys.accessToken, vectors.keys.accessToken);

  const exported = await crypto.subtle.exportKey(
    'raw',
    await crypto.subtle.importKey('raw', unhex(vectors.keys.boxKeyHex), 'AES-GCM', true, [
      'encrypt',
    ]),
  );
  assert.equal(hex(new Uint8Array(exported)), vectors.keys.boxKeyHex);
});

test('the three keys differ from each other', async () => {
  const keys = await deriveKeys(vectors.keys.claim);
  assert.notEqual(keys.deviceId, keys.accessToken);
  assert.notEqual(keys.accessToken, vectors.keys.boxKeyHex);
  // The device id is what the relay logs. If it ever equalled the claim code,
  // the key to every schedule would be sitting in a server access log.
  assert.notEqual(keys.deviceId, keys.claim);
});

// ── the envelope ────────────────────────────────────────────────────────────

async function sampleKey() {
  return crypto.subtle.importKey('raw', unhex(vectors.keys.boxKeyHex), 'AES-GCM', false, [
    'encrypt',
    'decrypt',
  ]);
}

test('the AAD string is byte-identical to the firmware', () => {
  assert.equal(
    new TextDecoder().decode(aad(vectors.envelope.deviceId, 'desired', 7)),
    vectors.envelope.aadExample,
  );
});

test('a Python-sealed schedule opens here', async () => {
  const { deviceId: id, desired } = vectors.envelope;
  const opened = await unseal(await sampleKey(), id, 'desired', desired.sealed);
  assert.deepEqual(opened, desired.plaintext);
});

test('a Python-sealed report opens here', async () => {
  const { deviceId: id, reported } = vectors.envelope;
  const opened = await unseal(await sampleKey(), id, 'reported', reported.sealed);
  assert.deepEqual(opened, reported.plaintext);
});

test('a moved slot or an edited revision fails the open', async () => {
  // The two substitutions that matter. Moving the slot plays the device's own
  // report of what it did back to it as an instruction; renumbering the
  // revision serves last month's prescription under today's number. Both are
  // things a relay operator could do by editing a file on disk, and both have
  // to fail closed rather than open into something plausible.
  const key = await sampleKey();
  for (const item of vectors.envelope.mustNotOpen) {
    await assert.rejects(
      () => unseal(key, vectors.envelope.deviceId, item.slot, item.sealed),
      SealError,
      item.why,
    );
  }
});

test('an envelope sealed for one device does not open for another', async () => {
  const key = await sampleKey();
  const sealed = await seal(key, vectors.envelope.deviceId, 'desired', 1, { payload: 'SC1*W*1:0800-127-000' });
  await assert.rejects(() => unseal(key, 'some-other-device', 'desired', sealed), SealError);
});

test('seal and unseal round-trip', async () => {
  const key = await sampleKey();
  const payload = { payload: 'SC1*W*1:0800.2000-127-030', note: 'round trip' };
  const sealed = await seal(key, vectors.envelope.deviceId, 'desired', 42, payload);
  assert.equal(sealed.rev, 42);
  assert.equal(sealed.alg, 'A256GCM');
  assert.equal(unb64url(sealed.iv).length, 12);
  assert.deepEqual(await unseal(key, vectors.envelope.deviceId, 'desired', sealed), payload);
});

test('two seals of the same payload differ — the IV is fresh each time', async () => {
  const key = await sampleKey();
  const one = await seal(key, vectors.envelope.deviceId, 'desired', 1, { payload: 'x' });
  const two = await seal(key, vectors.envelope.deviceId, 'desired', 1, { payload: 'x' });
  assert.notEqual(one.iv, two.iv);
  assert.notEqual(one.ct, two.ct);
});

// ── SC1*W* ──────────────────────────────────────────────────────────────────

test('encodeWeekly matches the firmware', () => {
  for (const item of vectors.weekly) {
    assert.equal(encodeWeekly(item.slots), item.payload);
  }
});

test('decodeWeekly is the inverse', () => {
  for (const item of vectors.weekly) {
    assert.deepEqual(decodeWeekly(item.payload), normaliseSlots(item.slots));
  }
});

test('times are parsed in every form a form field produces', () => {
  assert.equal(parseHhmm('08:00'), 480);
  assert.equal(parseHhmm('8:00'), 480);
  assert.equal(parseHhmm('0800'), 480);
  assert.equal(parseHhmm(' 0800 '), 480);
  assert.equal(parseHhmm('2400'), null);
  assert.equal(parseHhmm('0860'), null);
  assert.equal(parseHhmm('nope'), null);
  assert.equal(formatHhmm(480), '0800');
  assert.equal(formatHhmm(0), '0000');
  assert.equal(formatHhmm(1439), '2359');
});

test('a schedule the device would refuse is refused here first', () => {
  // Better to fail while somebody is still looking at the form than to have
  // the device refuse the whole thing after they have walked away.
  assert.throws(() => encodeWeekly([]), ScheduleError);
  assert.throws(() => encodeWeekly([{ tray: 0, times: ['0800'] }]), ScheduleError);
  assert.throws(() => encodeWeekly([{ tray: 9, times: ['0800'] }]), ScheduleError);
  assert.throws(() => encodeWeekly([{ tray: 1, times: [] }]), ScheduleError);
  assert.throws(() => encodeWeekly([{ tray: 1, times: ['0800', '08:00'] }]), ScheduleError);
  assert.throws(() => encodeWeekly([{ tray: 1, times: ['0800'], days: 0 }]), ScheduleError);
  assert.throws(() => encodeWeekly([{ tray: 1, times: ['0800'], days: 128 }]), ScheduleError);
  assert.throws(() => encodeWeekly([{ tray: 1, times: ['0800'], durationDays: 1000 }]), ScheduleError);
});

test('day masks convert both ways', () => {
  assert.equal(daysToMask([0, 2, 4]), 21); // Mon, Wed, Fri
  assert.deepEqual(maskToDays(21), [0, 2, 4]);
  assert.equal(describeDays(21), 'Mon, Wed, Fri');
  assert.equal(describeDays(EVERY_DAY), 'every day');
  assert.throws(() => daysToMask([]), ScheduleError);
  assert.throws(() => daysToMask([7]), ScheduleError);
});

test('decodeWeekly refuses malformed payloads rather than guessing', () => {
  assert.equal(decodeWeekly('SC1*S*1:0800'), null); // the lossy form, not this one
  assert.equal(decodeWeekly('SC1*W*1:0800-127'), null); // missing the duration
  assert.equal(decodeWeekly('SC1*W*1:0800-000-000'), null); // an empty day mask
  assert.equal(decodeWeekly('nonsense'), null);
});

// ── the relay client ────────────────────────────────────────────────────────

/** A relay that exists only in this file, so the tests need no network. */
function fakeRelay(routes: Record<string, () => Response>): typeof fetch {
  return (async (input: RequestInfo | URL, init?: RequestInit) => {
    const url = new URL(String(input));
    const key = `${init?.method ?? 'GET'} ${url.pathname}${url.search}`;
    const handler = routes[key] ?? routes[`${init?.method ?? 'GET'} ${url.pathname}`];
    if (!handler) throw new Error(`unexpected request: ${key}`);
    return handler();
  }) as typeof fetch;
}

const json = (body: unknown, status = 200) =>
  new Response(JSON.stringify(body), { status, headers: { 'Content-Type': 'application/json' } });

test('the client addresses the mailbox by derived id and bearer token', async () => {
  let seenAuth = '';
  let seenUrl = '';
  const client = await DispenserClient.pair({
    relayUrl: 'https://relay.example/',
    claim: vectors.keys.claim,
    fetchImpl: (async (input: RequestInfo | URL, init?: RequestInit) => {
      seenUrl = String(input);
      seenAuth = String(new Headers(init?.headers).get('Authorization'));
      return json({ ok: true, deviceId: vectors.keys.deviceId });
    }) as typeof fetch,
  });

  assert.equal(client.deviceId, vectors.keys.deviceId);
  await client.meta();
  // The trailing slash on relayUrl must not become a double slash.
  assert.equal(seenUrl, `https://relay.example/v1/devices/${vectors.keys.deviceId}`);
  assert.equal(seenAuth, `Bearer ${vectors.keys.accessToken}`);
});

test('setSchedule reads the current revision and writes the next one', async () => {
  let written: { envelope: { rev: number; ct: string } } | null = null;
  const client = await DispenserClient.pair({
    relayUrl: 'https://relay.example',
    claim: vectors.keys.claim,
    fetchImpl: (async (input: RequestInfo | URL, init?: RequestInit) => {
      if ((init?.method ?? 'GET') === 'GET') {
        return json({ ok: true, deviceId: vectors.keys.deviceId, desired: { rev: 6 } });
      }
      written = JSON.parse(String(init?.body));
      return json({ ok: true, rev: written!.envelope.rev });
    }) as typeof fetch,
  });

  const rev = await client.setSchedule([
    { tray: 1, times: ['0800', '2000'], days: EVERY_DAY, durationDays: 30 },
  ]);
  assert.equal(rev, 7, 'the next revision is current + 1, and we do not own the counter');
  assert.equal(written!.envelope.rev, 7);

  // And what went up is genuinely sealed — the relay cannot read the schedule.
  assert.ok(!JSON.stringify(written).includes('0800'));
  const opened = await unseal(await sampleKey(), vectors.keys.deviceId, 'desired', written!.envelope);
  assert.equal((opened as { payload: string }).payload, 'SC1*W*1:0800.2000-127-030');
});

test('a mailbox that does not exist yet is created by the first write', async () => {
  const client = await DispenserClient.pair({
    relayUrl: 'https://relay.example',
    claim: vectors.keys.claim,
    fetchImpl: (async (input: RequestInfo | URL, init?: RequestInit) => {
      if ((init?.method ?? 'GET') === 'GET') return json({ ok: false, error: 'no such device' }, 404);
      return json({ ok: true, rev: 1 });
    }) as typeof fetch,
  });
  assert.equal(await client.setSchedule([{ tray: 1, times: ['0800'] }]), 1);
});

test('a losing write surfaces as a conflict carrying the newer revision', async () => {
  // Two phones editing the same prescription. The loser is holding a stale
  // copy and must be shown the newer one, not allowed to retry over it.
  let getCount = 0;
  const client = await DispenserClient.pair({
    relayUrl: 'https://relay.example',
    claim: vectors.keys.claim,
    fetchImpl: (async (input: RequestInfo | URL, init?: RequestInit) => {
      if ((init?.method ?? 'GET') === 'GET') {
        getCount += 1;
        return json({ ok: true, desired: { rev: getCount === 1 ? 6 : 9 } });
      }
      return json({ ok: false, error: 'revision 7 is not newer than 9' }, 409);
    }) as typeof fetch,
  });

  await assert.rejects(
    () => client.setSchedule([{ tray: 1, times: ['0800'] }]),
    (error: unknown) => {
      assert.ok(error instanceof RevisionConflictError);
      assert.equal(error.status, 409);
      assert.equal(error.currentRev, 9);
      return true;
    },
  );
});

test('a long poll that finds nothing new resolves to null, not an error', async () => {
  const client = await DispenserClient.pair({
    relayUrl: 'https://relay.example',
    claim: vectors.keys.claim,
    fetchImpl: fakeRelay({
      [`GET /v1/devices/${vectors.keys.deviceId}/reported?since=3&wait=50`]: () =>
        new Response(null, { status: 204 }),
    }),
  });
  assert.equal(await client.waitForReport(3), null);
});

test('a report comes back opened and typed', async () => {
  const client = await DispenserClient.pair({
    relayUrl: 'https://relay.example',
    claim: vectors.keys.claim,
    fetchImpl: fakeRelay({
      [`GET /v1/devices/${vectors.keys.deviceId}/reported?since=0&wait=0`]: () =>
        json({ ok: true, rev: 3, envelope: vectors.envelope.reported.sealed }),
    }),
  });
  const found = await client.getReport();
  assert.equal(found!.rev, 3);
  assert.equal(found!.report.network.ssid, 'Home');
  assert.equal(found!.report.events[0].sc1, 'SC1*E*1*0800*T*07');
});

test('a relay error carries its status rather than being swallowed', async () => {
  const client = await DispenserClient.pair({
    relayUrl: 'https://relay.example',
    claim: vectors.keys.claim,
    fetchImpl: fakeRelay({
      [`GET /v1/devices/${vectors.keys.deviceId}/reported?since=0&wait=0`]: () =>
        json({ ok: false, error: 'that token does not open this mailbox' }, 403),
    }),
  });
  await assert.rejects(
    () => client.getReport(),
    (error: unknown) => error instanceof RelayError && error.status === 403,
  );
});

test('staleness is judged from the report timestamp, not from "connected"', () => {
  // A dispenser whose power has been pulled sends nothing and otherwise looks
  // identical to a healthy one. This is the check that tells them apart.
  // The stamps carry an offset. isStale treats one without as unknown, and the
  // two assertions below used to read '2026-08-01T09:15:00' — parsed in the
  // reader's own timezone, which is the carer's phone and not the dispenser.
  // They were written before that rule existed and had never been run since:
  // src/relay.ts used a constructor parameter property, so importing this file
  // threw and the whole suite died before a single test executed.
  const report = { ...vectors.envelope.reported.plaintext, at: '2026-08-01T09:15:00+09:00' };
  const soonAfter = new Date('2026-08-01T09:20:00+09:00');
  const muchLater = new Date('2026-08-01T14:00:00+09:00');
  assert.equal(DispenserClient.isStale(report as never, 15 * 60, soonAfter), false);
  assert.equal(DispenserClient.isStale(report as never, 15 * 60, muchLater), true);
  assert.equal(DispenserClient.isStale({ ...report, at: 'never' } as never), true);
});

test('a timestamp with no UTC offset counts as stale rather than being guessed', () => {
  // Older firmware sends a bare local time. Reading it in the phone's zone puts
  // a device in Seoul nine hours away from a carer in the UK — far past any
  // fifteen minute threshold, in whichever direction the pair happens to sit.
  // One direction shows a healthy dispenser as unplugged; the other hides one
  // that has been dead for days. "Go and look at it" is the recoverable half.
  const bare = { ...vectors.envelope.reported.plaintext, at: '2026-08-01T09:15:00' };
  const oneMinuteLater = new Date('2026-08-01T09:16:00+09:00');
  assert.equal(DispenserClient.isStale(bare as never, 15 * 60, oneMinuteLater), true);
  assert.equal(
    DispenserClient.isStale({ ...bare, at: '2026-08-01T09:15:00Z' } as never, 15 * 60,
      new Date('2026-08-01T09:16:00Z')),
    false,
  );
});
